import os
import six
from IQCommon import pandas as pd
from datetime import datetime
from IQCommon.logger import system_log
from IQCommon.exception import get_traceback_message
class MarketStorage(object):
    __doc__ = """
    市场信息存储
    """
    def __init__(self, path):
        self.latest_day = datetime.now().strftime('%Y%m%d')
        self.path = path
        self.load()
    def load(self):
        try:
            self._market = pd.read_pickle(self.path)
        except Exception as ex:
            system_log.error('市场路径{}错误'.format(os.path.abspath(self.path)))
            raise FileNotFoundError('市场信息路径{}错误,请改正后重试'.format(os.path.abspath(self.path)))
    def reload(self):
        tmp_now = datetime.now().strftime('%Y%m%d')
        if self.latest_day != tmp_now:
            self.load()
            self.latest_day = tmp_now
            return None
    def get_market_list(self):
        self.reload()
        try:
            market_list = self._market['market_list']
            return market_list
        except KeyError:
            system_log.error(get_traceback_message())
            return None
    def get_market_detail(self, finance_mic):
        self.reload()
        try:
            market_detail = self._market['market_detail']
            data = market_detail.get(finance_mic, [])
            if not data:
                system_log.warning('get_market_detail获取不到%s的数据' % finance_mic)
            return data
        except KeyError:
            system_log.error(get_traceback_message())
            return None
